import subprocess
from ipaddress import IPv4Network
def task_func(ip_range):
    network = IPv4Network(ip_range)
    active_status = {}
    for ip in network.hosts():
        param = '-n' if subprocess.os.name == 'nt' else '-c'
        command = ['ping', param, '1', str(ip)]
        try:
            result = subprocess.run(command, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=2)
            active_status[str(ip)] = result.returncode == 0
        except subprocess.CalledProcessError:
            raise
    return active_status

import subprocess
import ftplib
import os
def task_func(ftp_server='ftp.dlptest.com', ftp_user='dlpuser', ftp_password='rNrKYTX9g7z3RgJRmxWuGHbeu', ftp_dir='/ftp/test'):
    try:
