    return downloaded_files

import subprocess
import platform
import time
def task_func(url):
    system = platform.system()
    if system == 'Darwin':
        cmd = ['open', url]
    elif system == 'Windows':
        cmd = ['start', url]
    else:
        cmd = ['xdg-open', url]
    process = subprocess.Popen(cmd)
    time.sleep(0.5)
    return process.poll()

