import subprocess
import os
import shutil
from glob import glob
def task_func(src_folder, dst_folder):
    failed_files = []
    for file_path in glob(os.path.join(src_folder, '*')):
        try:
            subprocess.run(['gzip', file_path], check=True)
            shutil.move(file_path + '.gz', dst_folder)
        except Exception:
            failed_files.append(os.path.basename(file_path))
    success = len(failed_files) == 0
    message = 'All files compressed and moved successfully' if success else 'Some files failed to compress or move'
    return {'success': success, 'message': message, 'failed_files': failed_files}

import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script not found: {script_path}")
    cpu_usage = 0.0
    memory_usage = 0
    try:
        proc = subprocess.Popen(['bash', script_path])
        start_time = time.time()
        while True:
            try:
                p = psutil.Process(proc.pid)
                cpu_usage += p.cpu_percent(interval=0.1)
                memory_usage += p.memory_info().rss
            except (psutil.NoSuchProcess, psutil.ZombieProcess):
                break
            if proc.poll() is not None:
                break
            if time.time() - start_time > timeout:
                proc.terminate()
                proc.wait()
                break
    except Exception:
        if proc.poll() is None:
            proc.terminate()
    return {'CPU Usage': cpu_usage, 'Memory Usage': memory_usage}

import subprocess
import logging
def task_func(filepath):
